window.QB_TKP = [
{id:"TKP-001", q:"Anda bertugas di loket pelayanan administrasi kelurahan. Seorang warga lanjut usia datang dengan berkas KTP yang tidak lengkap dan terlihat bingung dengan prosedur. Antrean di belakangnya cukup panjang. Sikap yang paling tepat adalah ....", opts:[{t:"Menjelaskan dengan sabar dan ramah persyaratan yang kurang, lalu membantu menyiapkan berkasnya agar tidak perlu bolak-balik", s:5},{t:"Meminta warga tersebut melengkapi berkasnya terlebih dahulu sambil memberikan daftar persyaratan tertulis", s:4},{t:"Melayani warga berikutnya dan meminta warga lanjut usia tersebut bertanya ke petugas informasi", s:3},{t:"Menyuruh warga tersebut pulang dan kembali lagi setelah berkasnya lengkap tanpa penjelasan", s:2},{t:"Menolak melayani karena berkas tidak lengkap dan menegurnya di depan antrean", s:1}], ex:"Pelayanan prima mengutamakan kemudahan dan keramahan, terutama bagi kelompok rentan; membantu menyiapkan berkas menunjukkan empati dan orientasi solusi."},
{id:"TKP-002", q:"Seorang ibu hamil terlihat kelelahan setelah mengantre lama di loket Anda. Tindakan yang paling tepat adalah ....", opts:[{t:"Membiarkannya tetap mengantre karena semua warga harus diperlakukan sama", s:3},{t:"Menawarkan kursi tunggu prioritas dan memanggilnya lebih dahulu dengan sopan sambil menjelaskan ke antrean", s:5},{t:"Menawarkan kursi tunggu prioritas namun tetap sesuai urutan antrean", s:4},{t:"Menyuruhnya pulang dan datang lagi besok pagi-pagi agar tidak antre lama", s:2},{t:"Menegurnya karena tidak datang lebih pagi", s:1}], ex:"Kelompok prioritas (lansia, ibu hamil, penyandang disabilitas) berhak mendapat layanan prioritas sesuai standar pelayanan publik."},
{id:"TKP-003", q:"Seorang penyandang disabilitas pengguna kursi roda ingin mengurus surat di loket lantai 2, padahal gedung tidak memiliki lift. Yang paling tepat Anda lakukan adalah ....", opts:[{t:"Meminta keluarga warga membantu mengangkat kursi rodanya ke lantai 2", s:3},{t:"Turun ke lantai 1 dan melayaninya langsung di tempat yang mudah diakses", s:5},{t:"Meminta rekan membantu membawakan berkasnya ke loket lantai 2", s:4},{t:"Menyuruhnya datang bersama pendamping yang kuat lain waktu", s:2},{t:"Menolak melayani dengan alasan keterbatasan fasilitas gedung", s:1}], ex:"Pelayanan inklusif mewajibkan petugas yang menyesuaikan diri dengan kebutuhan penyandang disabilitas, bukan sebaliknya."},
{id:"TKP-004", q:"Seorang warga marah-marah karena sudah menunggu dua jam tanpa kejelasan. Sikap Anda yang paling tepat adalah ....", opts:[{t:"Membalas dengan nada tinggi agar warga tersebut diam dan tidak mengganggu", s:2},{t:"Tetap tenang, meminta maaf atas keterlambatan, menjelaskan penyebabnya, dan mempercepat prosesnya", s:5},{t:"Meminta maaf dan mempersilakannya duduk sambil menunggu giliran", s:4},{t:"Menjelaskan bahwa antrean memang panjang dan memintanya bersabar", s:3},{t:"Memanggil petugas keamanan untuk menenangkan warga tersebut", s:1}], ex:"Mengelola emosi warga dengan empati dan penjelasan transparan adalah inti pelayanan prima; membalas emosi hanya memperburuk situasi."},
{id:"TKP-005", q:"Sistem aplikasi pelayanan sedang mati total, sementara seorang warga membutuhkan surat keterangan mendesak untuk keperluan rawat inap keluarganya. Tindakan terbaik adalah ....", opts:[{t:"Meminta warga menunggu hingga sistem pulih tanpa kepastian waktu", s:3},{t:"Membuatkan surat keterangan manual resmi yang ditandatangani pejabat berwenang sambil menjelaskan situasinya", s:5},{t:"Mencatat data warga dan berjanji menghubunginya begitu sistem pulih", s:4},{t:"Menyuruh warga mengurus ke dinas lain yang sistemnya menyala", s:2},{t:"Menolak melayani dengan alasan sistem sedang mati", s:1}], ex:"Dalam keadaan darurat petugas harus mencari solusi alternatif yang sah agar kebutuhan mendesak warga tetap terpenuhi."},
{id:"TKP-006", q:"Seorang warga menyelipkan 'uang rokok' agar berkasnya didahulukan dari antrean. Respons Anda yang paling tepat adalah ....", opts:[{t:"Menerima uangnya tetapi tetap melayani sesuai urutan antrean", s:2},{t:"Menolak dengan sopan, menjelaskan semua dilayani sesuai antrean, dan tetap melayaninya sesuai giliran", s:5},{t:"Menolak pemberian tersebut dan melaporkannya ke atasan sebagai dugaan gratifikasi", s:4},{t:"Berpura-pura tidak melihat dan tetap melayani sesuai antrean", s:3},{t:"Menerima dan mendahulukan berkasnya", s:1}], ex:"Menolak gratifikasi secara tegas namun sopan sekaligus menegakkan prinsip antrean menunjukkan integritas pelayanan."},
{id:"TKP-007", q:"Pada jam istirahat, seorang warga yang datang dari luar kota jauh-jauh membutuhkan legalisasi dokumen untuk keperluan esok hari. Yang paling tepat adalah ....", opts:[{t:"Meminta warga menunggu hingga jam istirahat selesai sambil menjelaskan", s:4},{t:"Melayaninya terlebih dahulu karena datang dari jauh, lalu beristirahat setelahnya", s:5},{t:"Menyuruh warga kembali setelah jam istirahat selesai", s:3},{t:"Menyuruh warga datang lagi besok pagi", s:2},{t:"Menutup loket di depannya tanpa penjelasan", s:1}], ex:"Fleksibilitas demi kemaslahatan warga yang menempuh jarak jauh mencerminkan pelayanan yang berorientasi pada kebutuhan."},
{id:"TKP-008", q:"Seorang warga yang tidak bisa membaca dan menulis perlu mengisi formulir permohonan. Bantuan terbaik yang dapat Anda berikan adalah ....", opts:[{t:"Memberikan contoh formulir yang sudah terisi agar ditiru", s:3},{t:"Membantu mengisikan formulir sambil membacakan setiap kolom dan meminta konfirmasi kebenarannya", s:5},{t:"Meminta warga membawa formulir yang sudah diisikan orang lain", s:4},{t:"Menyuruh warga belajar dulu cara mengisi formulir", s:2},{t:"Menolak karena formulir harus diisi sendiri oleh pemohon", s:1}], ex:"Membantu warga yang buta huruf dengan tetap menjaga keakuratan data adalah wujud pelayanan yang manusiawi."},
{id:"TKP-009", q:"Keluhan tentang lambatnya pelayanan di unit Anda menjadi viral di media sosial. Langkah paling tepat adalah ....", opts:[{t:"Membalas dengan nada defensif dan menyalahkan warga yang mengeluh", s:2},{t:"Menanggapi secara resmi dengan empati, menjelaskan perbaikan yang dilakukan, dan mengajak berdialog", s:5},{t:"Menyampaikan klarifikasi singkat melalui akun resmi instansi", s:4},{t:"Mengabaikannya karena bukan tugas Anda menjawab media sosial", s:3},{t:"Meminta admin menghapus komentar keluhan tersebut", s:1}], ex:"Keluhan publik harus dijawab transparan dan solutif; menghapus kritik justru merusak kepercayaan masyarakat."},
{id:"TKP-010", q:"Seorang warga sudah mengantre satu jam tetapi ternyata salah loket. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Memberitahu loket yang benar dan memintanya mengantre ulang dari awal", s:3},{t:"Mengantar atau mengarahkan langsung ke loket yang benar dan memastikan ia segera dilayani", s:5},{t:"Menjelaskan loket yang benar dan memberikan nomor antrean prioritas", s:4},{t:"Menyalahkan warga karena tidak membaca papan informasi", s:2},{t:"Membiarkannya karena bukan urusan Anda", s:1}], ex:"Kesalahan warga menjadi tanggung jawab moral petugas untuk diperbaiki dengan pendampingan, bukan dibiarkan."},
{id:"TKP-011", q:"Anak magang di unit Anda salah menginput data sehingga surat keterangan warga tercetak keliru. Yang paling tepat dilakukan adalah ....", opts:[{t:"Menyalahkan anak magang di depan warga agar ia jera", s:3},{t:"Meminta maaf kepada warga, memperbaiki data, mencetak ulang, dan membimbing magang agar tidak terulang", s:5},{t:"Memperbaiki dan mencetak ulang tanpa penjelasan apa pun", s:4},{t:"Menyuruh warga datang lagi besok karena kesalahan internal", s:2},{t:"Menyuruh warga membayar biaya cetak ulang", s:1}], ex:"Kesalahan internal menjadi tanggung jawab unit; memperbaikinya segera sambil membina bawahan menunjukkan kepemimpinan yang baik."},
{id:"TKP-012", q:"Seorang warga meminta tolong difotokopikan berkas pribadinya, padahal itu bukan wewenang loket Anda. Sikap terbaik adalah ....", opts:[{t:"Menolak membantu karena bukan tugas Anda", s:3},{t:"Membantu sebisanya atau mengarahkan ke tempat fotokopi terdekat sambil tetap melayani keperluan utamanya", s:5},{t:"Menjelaskan bahwa itu bukan wewenang Anda lalu melayani keperluan utamanya", s:4},{t:"Memarahi warga karena merepotkan", s:2},{t:"Mengabaikan permintaannya sama sekali", s:1}], ex:"Keramahan membantu hal kecil yang masih wajar memperkuat citra pelayanan publik."},
{id:"TKP-013", q:"Seorang warga tunanetra perlu menandatangani dokumen penting. Perlakuan yang paling tepat adalah ....", opts:[{t:"Langsung mengarahkan tangannya ke kolom tanda tangan", s:3},{t:"Membacakan seluruh isi dokumen dengan jelas sebelum ia menandatangani, dan menawarkan kehadiran saksi", s:5},{t:"Membacakan ringkasan isi dokumennya saja", s:4},{t:"Meminta orang lain menandatangani untuknya", s:2},{t:"Menolak karena berisiko di kemudian hari", s:1}], ex:"Hak warga difabel atas informasi penuh sebelum menandatangani harus dipenuhi dengan membacakan dokumen secara utuh."},
{id:"TKP-014", q:"Sistem antrean daring error; seorang warga sudah mendaftar online tetapi namanya tidak muncul di daftar. Keputusan terbaik adalah ....", opts:[{t:"Menyuruhnya mengantre dari awal seperti pengunjung biasa", s:3},{t:"Memverifikasi bukti pendaftaran di ponselnya dan melayaninya sesuai urutan kedatangan", s:5},{t:"Memintanya mendaftar ulang secara manual di tempat", s:4},{t:"Menyalahkan sistem dan menyuruhnya pulang", s:2},{t:"Menolak karena namanya tidak terdaftar", s:1}], ex:"Bukti pendaftaran daring yang valid harus dihormati; kegagalan sistem tidak boleh merugikan warga."},
{id:"TKP-015", q:"Seorang warga membawa balita yang rewel saat mengurus berkas di loket Anda. Sikap terbaik adalah ....", opts:[{t:"Meminta warga menenangkan anaknya dulu di luar ruangan", s:3},{t:"Melayani dengan cepat dan ramah, sesekali menyapa anaknya agar tenang", s:5},{t:"Mempercepat proses tanpa basa-basi", s:4},{t:"Menunjukkan wajah kesal agar warga cepat selesai", s:2},{t:"Menolak melayani hingga anaknya diam", s:1}], ex:"Empati pada orang tua yang membawa anak menunjukkan pelayanan yang manusiawi sekaligus efisien."},
{id:"TKP-016", q:"Seorang warga mengeluh menjadi korban pungli oleh oknum di unit lain. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengatakan itu bukan wewenang Anda", s:3},{t:"Mencatat laporan lengkap, menjelaskan jalur pengaduan resmi, dan meneruskannya ke atasan atau inspektorat", s:5},{t:"Menyarankan warga melapor ke kanal saber pungli", s:4},{t:"Membela oknum tersebut karena rekan seprofesi", s:2},{t:"Mengancam warga agar tidak menyebar fitnah", s:1}], ex:"Laporan pungli harus ditindaklanjuti melalui mekanisme resmi; menutupinya sama dengan melindungi pelanggaran."},
{id:"TKP-017", q:"Banjir melanda wilayah Anda dan banyak warga membutuhkan surat keterangan domisili untuk pengungsian dan bantuan. Langkah terbaik unit Anda adalah ....", opts:[{t:"Melayani seperti biasa sesuai urutan antrean", s:3},{t:"Membuka layanan darurat atau keliling dan memprioritaskan surat bagi warga terdampak", s:5},{t:"Tetap melayani di kantor dengan memprioritaskan korban banjir", s:4},{t:"Menutup layanan sementara karena banjir", s:2},{t:"Meminta warga menunggu hingga situasi normal kembali", s:1}], ex:"Kondisi darurat menuntut respons luar biasa; pelayanan harus hadir justru saat warga paling membutuhkan."},
{id:"TKP-018", q:"Seorang warga lanjut usia tidak memiliki ponsel untuk menerima kode verifikasi (OTP) aplikasi layanan. Solusi terbaik adalah ....", opts:[{t:"Menyuruh warga membeli ponsel terlebih dahulu", s:2},{t:"Menggunakan jalur verifikasi alternatif seperti KTP fisik atau wawancara sesuai prosedur", s:5},{t:"Meminta bantuan anggota keluarga yang memiliki ponsel", s:4},{t:"Menyuruh warga pulang dan kembali lain waktu", s:3},{t:"Menolak dengan alasan sistem mengharuskan OTP", s:1}], ex:"Transformasi digital tidak boleh mengecualikan warga yang belum terdigitalisasi; sediakan jalur alternatif yang sah."},
{id:"TKP-019", q:"Program pelayanan jemput bola ke desa terpencil sepi peminat karena warga sedang musim panen. Yang paling tepat dilakukan adalah ....", opts:[{t:"Pulang dan menjadwalkan ulang bulan depan", s:3},{t:"Menyesuaikan jadwal kunjungan dengan waktu luang warga seperti sore hari dan mengumumkannya lewat perangkat desa", s:5},{t:"Tetap menunggu di balai desa hingga warga selesai panen", s:4},{t:"Melaporkan warga tidak kooperatif ke atasan", s:2},{t:"Membatalkan program jemput bola", s:1}], ex:"Pelayanan jemput bola harus adaptif terhadap ritme kehidupan warga yang menjadi sasaran."},
{id:"TKP-020", q:"Permohonan seorang warga harus ditolak karena tidak memenuhi syarat. Cara menyampaikan yang paling tepat adalah ....", opts:[{t:"Menyerahkan surat penolakan tanpa penjelasan", s:3},{t:"Menjelaskan alasan penolakan dengan bahasa sederhana, menunjukkan dasar aturannya, dan memberi tahu syarat agar bisa disetujui", s:5},{t:"Menjelaskan alasan penolakan secara singkat", s:4},{t:"Menyuruh warga menerima keputusan apa adanya", s:2},{t:"Mengusir warga yang protes atas penolakan", s:1}], ex:"Penolakan yang dijelaskan transparan dan solutif menjaga kepercayaan warga pada keadilan prosedur."},
{id:"TKP-021", q:"Rekan satu loket izin mendadak sehingga antrean menumpuk di loket Anda seorang. Tindakan terbaik adalah ....", opts:[{t:"Menutup loket sementara untuk beristirahat", s:2},{t:"Tetap melayani dengan tenang, meminta bantuan rekan unit lain, dan menginformasikan estimasi tunggu kepada warga", s:5},{t:"Melayani sendiri secepat mungkin tanpa bantuan", s:4},{t:"Menyalahkan rekan yang izin di depan warga", s:3},{t:"Membiarkan antrean tanpa penjelasan", s:1}], ex:"Krisis personel diatasi dengan kolaborasi dan komunikasi jujur kepada warga mengenai waktu tunggu."},
{id:"TKP-022", q:"Seorang warga meminta data pribadi tetangganya yang tersimpan di arsip kependudukan. Respons yang tepat adalah ....", opts:[{t:"Menolak tanpa penjelasan", s:3},{t:"Menolak dengan sopan sambil menjelaskan aturan perlindungan data pribadi", s:5},{t:"Memberikan sebagian informasi yang dinilai tidak penting", s:4},{t:"Memberikannya dengan imbalan tertentu", s:2},{t:"Memberikan semua data yang diminta", s:1}], ex:"Data pribadi warga dilindungi undang-undang; menolak dengan penjelasan edukatif adalah tindakan yang tepat."},
{id:"TKP-023", q:"Seorang warga hanya fasih berbahasa daerah dan tidak memahami penjelasan Anda. Yang paling tepat dilakukan adalah ....", opts:[{t:"Meminta warga kembali dengan penerjemah", s:3},{t:"Meminta bantuan rekan atau perangkat desa sebagai penerjemah dan memastikan ia memahami haknya", s:5},{t:"Berkomunikasi dengan bahasa isyarat dan gambar seadanya", s:4},{t:"Melayani seadanya tanpa memastikan ia paham", s:2},{t:"Menolak melayani karena kendala bahasa", s:1}], ex:"Kendala bahasa diatasi dengan mencari bantuan penerjemah, bukan dengan menolak warga."},
{id:"TKP-024", q:"Seorang warga datang lima menit sebelum jam tutup untuk urusan yang membutuhkan waktu tiga puluh menit. Keputusan terbaik adalah ....", opts:[{t:"Meminta warga datang lagi besok pagi", s:3},{t:"Tetap melayaninya hingga selesai karena ia datang dalam jam layanan", s:5},{t:"Melayani sebagian dan meminta kembali besok untuk sisanya", s:4},{t:"Menutup loket tepat waktu di depannya", s:2},{t:"Memarahi warga karena datang terlambat", s:1}], ex:"Warga yang datang dalam jam layanan berhak dilayani hingga tuntas."},
{id:"TKP-025", q:"Hasil survei kepuasan masyarakat menunjukkan nilai unit Anda rendah. Respons profesional yang paling tepat adalah ....", opts:[{t:"Menganggap hasil survei tidak akurat", s:3},{t:"Menganalisis akar masalah bersama tim, menyusun rencana perbaikan, dan memantau hasilnya", s:5},{t:"Mengadakan evaluasi internal tanpa tindak lanjut", s:4},{t:"Menyalahkan warga yang memberi nilai rendah", s:2},{t:"Mengabaikan hasil survei tersebut", s:1}], ex:"Umpan balik negatif adalah bahan perbaikan; respons profesional adalah evaluasi dan aksi konkret yang terukur."},
{id:"TKP-026", q:"Seorang vendor menawarkan 'uang terima kasih' setelah proyek pengadaan selesai dikerjakan. Sikap Anda yang paling tepat adalah ....", opts:[{t:"Menerima karena proyek sudah selesai dan tidak ada konflik kepentingan", s:3},{t:"Menolak dengan tegas dan melaporkannya ke atasan atau unit pengendalian gratifikasi", s:5},{t:"Menolak dengan halus tanpa melaporkannya", s:4},{t:"Meminta ditransfer diam-diam agar tidak ketahuan", s:2},{t:"Menerima dan membagikannya dengan tim", s:1}], ex:"Gratifikasi dalam bentuk apa pun dilarang bagi ASN; menolak dan melaporkan adalah standar integritas."},
{id:"TKP-027", q:"Atasan meminta Anda memanipulasi data laporan agar kinerja unit terlihat bagus. Tindakan yang paling tepat adalah ....", opts:[{t:"Menuruti karena itu perintah atasan langsung", s:3},{t:"Menolak dengan sopan, menjelaskan risiko hukumnya, dan menawarkan menyajikan data apa adanya dengan narasi perbaikan", s:5},{t:"Menolak tanpa penjelasan panjang", s:4},{t:"Menuruti sambil menyimpan bukti untuk berjaga-jaga", s:2},{t:"Memanipulasi lebih jauh agar atasan semakin senang", s:1}], ex:"Perintah atasan tidak membenarkan pelanggaran; ASN wajib menolak perintah yang melanggar hukum."},
{id:"TKP-028", q:"Anda menemukan selisih kas kecil yang tidak dapat dijelaskan oleh bendahara. Langkah terbaik adalah ....", opts:[{t:"Mengabaikannya karena nominalnya kecil", s:3},{t:"Melaporkan temuan secara tertulis ke pejabat berwenang untuk diaudit", s:5},{t:"Menanyakan langsung ke bendahara dan meminta penjelasan", s:4},{t:"Menutupinya dengan dana pribadi agar tidak ribut", s:2},{t:"Ikut mengambil karena menganggap semua orang juga begitu", s:1}], ex:"Temuan keuangan sekecil apa pun harus dilaporkan melalui jalur resmi untuk menjaga akuntabilitas."},
{id:"TKP-029", q:"Seorang rekan meminta Anda menandatangani dokumen yang belum Anda baca dengan alasan terburu-buru. Yang paling tepat adalah ....", opts:[{t:"Menandatangani karena percaya pada rekan tersebut", s:3},{t:"Menolak menandatangani sebelum membaca dan memverifikasi isinya", s:5},{t:"Membaca cepat lalu menandatangani", s:4},{t:"Menandatangani tanpa membaca agar cepat selesai", s:2},{t:"Menandatangani lalu meminta rekan bertanggung jawab bila bermasalah", s:1}], ex:"Tanda tangan adalah pertanggungjawaban hukum; menandatangani tanpa verifikasi adalah kelalaian profesional."},
{id:"TKP-030", q:"Perusahaan milik keluarga Anda mengikuti tender proyek di dinas tempat Anda bertugas sebagai panitia. Sikap paling tepat adalah ....", opts:[{t:"Tetap bertugas tetapi berusaha bersikap objektif", s:4},{t:"Mengundurkan diri dari kepanitiaan dan melaporkan potensi konflik kepentingan", s:5},{t:"Merahasiakan hubungan keluarga tersebut", s:3},{t:"Memberi bocoran informasi tender kepada keluarga", s:2},{t:"Memastikan perusahaan keluarga memenangkan tender", s:1}], ex:"Konflik kepentingan harus dihindari dengan mundur dari proses, bukan sekadar berjanji bersikap objektif."},{id:"TKP-031", q:"Seorang rekan kerja sering datang terlambat dan pulang lebih cepat sehingga bebannya jatuh kepada Anda. Tindakan paling tepat adalah ....", opts:[{t:"Mengerjakan saja sambil mengeluh kepada rekan lain", s:3},{t:"Membicarakannya baik-baik dengan rekan tersebut, dan bila tidak berubah melaporkannya ke atasan", s:5},{t:"Melaporkan langsung ke atasan tanpa bicara terlebih dahulu", s:4},{t:"Ikut-ikutan datang terlambat sebagai bentuk protes", s:2},{t:"Menyabotase pekerjaannya sebagai balasan", s:1}], ex:"Masalah disiplin diselesaikan lewat komunikasi langsung lalu jalur formal, bukan pembiaran atau pembalasan."},
{id:"TKP-032", q:"Seorang kerabat meminta Anda membocorkan soal ujian seleksi internal yang Anda ketahui. Respons terbaik adalah ....", opts:[{t:"Memberi kisi-kisi umum yang dinilai tidak apa-apa", s:3},{t:"Menolak dengan tegas karena melanggar prinsip keadilan dan kerahasiaan", s:5},{t:"Menolak dengan alasan tidak memiliki akses", s:4},{t:"Membocorkan sebagian soal saja", s:2},{t:"Membocorkan seluruh soal kepada kerabat", s:1}], ex:"Kebocoran soal merusak meritokrasi; penolakan tegas melindungi integritas seleksi."},
{id:"TKP-033", q:"Anda mengetahui atasan melakukan penyimpangan penggunaan anggaran. Langkah yang paling tepat adalah ....", opts:[{t:"Diam karena takut karier terancam", s:3},{t:"Melaporkan melalui kanal whistleblowing resmi dengan bukti yang dimiliki", s:5},{t:"Menegur atasan secara pribadi", s:4},{t:"Ikut menikmati hasil penyimpangan tersebut", s:2},{t:"Membantu menutupi jejak penyimpangan", s:1}], ex:"Mekanisme whistleblowing melindungi pelapor; diam berarti membiarkan kerugian negara terus terjadi."},
{id:"TKP-034", q:"Anda diminta membuat laporan kegiatan fiktif untuk menyerap sisa anggaran. Sikap terbaik adalah ....", opts:[{t:"Membuat laporan fiktif karena itu perintah", s:3},{t:"Menolak dan mengusulkan kegiatan nyata yang bermanfaat sebagai gantinya", s:5},{t:"Menolak tanpa memberikan usulan alternatif", s:4},{t:"Membuat laporan fiktif dan mengambil bagiannya", s:2},{t:"Mengusulkan mark-up anggaran yang lebih besar", s:1}], ex:"Kegiatan fiktif adalah korupsi; ASN profesional menawarkan alternatif kegiatan yang sah."},
{id:"TKP-035", q:"Seorang rekan memplagiat laporan yang Anda susun dan mengklaimnya sebagai karyanya di depan atasan. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya demi menjaga hubungan baik", s:3},{t:"Mengklarifikasi kepemilikan karya secara profesional kepada atasan dengan bukti yang dimiliki", s:5},{t:"Menegur rekan tersebut secara pribadi", s:4},{t:"Memplagiat balik karya miliknya", s:2},{t:"Menyebarkan keburukannya ke seluruh kantor", s:1}], ex:"Klaim atas karya dilindungi dengan bukti dan jalur formal, bukan dengan konflik terbuka."},
{id:"TKP-036", q:"Ada tekanan dari pihak politik agar Anda memprioritaskan pendukungnya dalam pelayanan. Sikap Anda yang paling tepat adalah ....", opts:[{t:"Memberi prioritas diam-diam agar aman", s:3},{t:"Menolak dan tetap melayani berdasarkan aturan dan urutan yang adil bagi semua", s:5},{t:"Menolak dengan alasan prosedur yang berlaku", s:4},{t:"Memberi prioritas secara terang-terangan", s:2},{t:"Menjadikan pendukungnya sebagai perantara resmi layanan", s:1}], ex:"Netralitas dan kesetaraan layanan adalah prinsip ASN; tekanan politik tidak boleh mengubahnya."},
{id:"TKP-037", q:"Anda diminta lembur tanpa uang lembur untuk mengejar tenggat pekerjaan yang penting. Sikap terbaik adalah ....", opts:[{t:"Menolak lembur karena tidak dibayar", s:3},{t:"Bersedia lembur demi tanggung jawab, lalu mengusulkan ke atasan agar hak lembur diperjuangkan sesuai aturan", s:5},{t:"Bersedia lembur tanpa menuntut apa pun", s:4},{t:"Lembur tetapi bekerja asal-asalan", s:2},{t:"Menghasut rekan untuk menolak lembur bersama", s:1}], ex:"Tanggung jawab pada target diutamakan, namun hak pekerja tetap diperjuangkan melalui jalur yang benar."},
{id:"TKP-038", q:"Karena jabatan Anda, Anda memiliki akses ke pangkalan data kependudukan warga. Prinsip yang paling tepat adalah ....", opts:[{t:"Sesekali mengecek data kenalan karena penasaran", s:3},{t:"Mengakses hanya untuk keperluan tugas resmi dan menjaga kerahasiaannya", s:5},{t:"Tidak pernah mengakses di luar keperluan tugas", s:4},{t:"Memberikan data kepada pihak ketiga yang mengaku membutuhkan", s:2},{t:"Menjual data kepada pihak yang berminat", s:1}], ex:"Data pribadi hanya boleh diakses untuk tugas resmi; penyalahgunaannya adalah pelanggaran hukum."},
{id:"TKP-039", q:"Sebuah dokumen penting hilang dari meja Anda menjelang audit. Tindakan paling tepat adalah ....", opts:[{t:"Berharap auditor tidak menyadarinya", s:3},{t:"Segera melapor ke atasan, mencari bersama, dan menyiapkan dokumen pengganti yang sah bila diperlukan", s:5},{t:"Mencari sendiri diam-diam tanpa melapor", s:4},{t:"Memalsukan dokumen pengganti agar terlihat lengkap", s:2},{t:"Menyalahkan rekan lain atas hilangnya dokumen", s:1}], ex:"Kejujuran dan keterbukaan saat terjadi kelalaian memungkinkan penyelesaian melalui jalur resmi."},
{id:"TKP-040", q:"Seseorang menawarkan jabatan kepada Anda dengan syarat membayar 'setoran' ke pejabat tertentu. Respons terbaik adalah ....", opts:[{t:"Mempertimbangkannya karena jenjang karier penting", s:3},{t:"Menolak dan melaporkan praktik jual beli jabatan ke kanal resmi", s:5},{t:"Menolak tawaran tersebut", s:4},{t:"Membayar setoran yang diminta", s:2},{t:"Membayar setoran sekaligus mencari bekingan tambahan", s:1}], ex:"Jual beli jabatan adalah korupsi; menolak dan melapor melindungi meritokrasi."},
{id:"TKP-041", q:"Seorang rekan mengajak Anda memalsukan absensi kehadiran. Sikap yang paling tepat adalah ....", opts:[{t:"Ikut sesekali saja agar tidak ketahuan", s:3},{t:"Menolak dan tetap mengisi absensi dengan jujur", s:5},{t:"Menolak ajakannya", s:4},{t:"Ikut memalsukan secara rutin", s:2},{t:"Menjadi koordinator pemalsuan absensi", s:1}], ex:"Integritas dimulai dari hal kecil seperti kehadiran yang jujur dan dapat dipertanggungjawabkan."},
{id:"TKP-042", q:"Anda menemukan kesalahan perhitungan tunjangan yang merugikan diri Anda sendiri. Langkah terbaik adalah ....", opts:[{t:"Membiarkannya karena malas mengurus administrasi", s:3},{t:"Melaporkan ke bagian kepegawaian atau keuangan dengan data pendukung untuk diperbaiki", s:5},{t:"Menanyakannya langsung ke bendahara", s:4},{t:"Mengambil kompensasi sendiri dari kas kantor", s:2},{t:"Menyebarkan isu bahwa kantor melakukan korupsi", s:1}], ex:"Hak yang dirugikan diperjuangkan melalui jalur resmi dengan bukti yang jelas."},
{id:"TKP-043", q:"Atasan mempresentasikan hasil kerja tim ke pimpinan tetapi hanya menyebut namanya sendiri. Sikap profesional Anda adalah ....", opts:[{t:"Membiarkan karena atasan memang pemimpin tim", s:4},{t:"Tetap profesional; menyampaikan kontribusi tim melalui laporan tertulis resmi tanpa menjatuhkan atasan", s:5},{t:"Protes langsung di depan pimpinan", s:3},{t:"Menyebarkan bahwa atasan mencuri kredit kerja", s:2},{t:"Berhenti berkontribusi agar atasan gagal", s:1}], ex:"Pengakuan atas karya diperjuangkan lewat dokumentasi resmi, bukan lewat konflik terbuka."},
{id:"TKP-044", q:"Anda diminta menjadi saksi yang 'mendukung' versi atasan dalam pemeriksaan internal, padahal tidak sesuai fakta. Tindakan terbaik adalah ....", opts:[{t:"Menjadi saksi tetapi memilih diam saja", s:3},{t:"Menolak dan bersedia memberikan keterangan sesuai fakta yang sebenarnya", s:5},{t:"Menolak menjadi saksi", s:4},{t:"Mendukung versi atasan demi loyalitas", s:2},{t:"Membuat kesaksian palsu yang menguatkan versinya", s:1}], ex:"Kesaksian palsu adalah pelanggaran hukum; ASN wajib berpegang pada fakta yang sebenarnya."},
{id:"TKP-045", q:"Pekerjaan Anda menumpuk karena kebiasaan menunda-nunda. Langkah paling bertanggung jawab adalah ....", opts:[{t:"Meminta perpanjangan tenggat kepada atasan", s:3},{t:"Menyusun prioritas, meminta maaf bila ada pihak terdampak, dan menyelesaikannya sesuai tenggat dengan mengatur ulang jadwal", s:5},{t:"Lembur untuk mengejar ketertinggalan", s:4},{t:"Menyalahkan beban kerja yang terlalu banyak", s:2},{t:"Membiarkan tenggat lewat begitu saja", s:1}], ex:"Tanggung jawab atas keterlambatan diwujudkan dengan rencana penyelesaian yang konkret, bukan alasan."},
{id:"TKP-046", q:"Seorang rekan satu tim jatuh sakit menjelang tenggat laporan penting. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Mengerjakan tugas sendiri saja sesuai porsi", s:3},{t:"Mengambil alih tugas kritisnya sambil berkoordinasi dengan tim agar tenggat terpenuhi", s:5},{t:"Membagi tugasnya kepada seluruh anggota tim", s:4},{t:"Meminta atasan menunda tenggat laporan", s:2},{t:"Membiarkan tenggat lewat karena itu bukan tugas Anda", s:1}], ex:"Solidaritas tim diwujudkan dengan gotong royong menutup kekosongan demi target bersama."},
{id:"TKP-047", q:"Dalam rapat terjadi perbedaan pendapat yang tajam antara Anda dan rekan soal metode kerja. Cara terbaik menyikapinya adalah ....", opts:[{t:"Mengalah demi menjaga keharmonisan", s:4},{t:"Menyampaikan argumen dengan data, mendengarkan pandangannya, dan mencari titik temu terbaik untuk tim", s:5},{t:"Memaksakan pendapat karena merasa lebih senior", s:3},{t:"Membawa masalah ke luar rapat menjadi bahan gosip", s:2},{t:"Menolak bekerja sama dengannya setelah rapat", s:1}], ex:"Perbedaan pendapat diselesaikan dengan dialog berbasis data dan berorientasi pada hasil tim."},
{id:"TKP-048", q:"Program kerja Anda membutuhkan data dari dinas lain yang lambat merespons permintaan resmi. Langkah paling efektif adalah ....", opts:[{t:"Mengirim surat resmi untuk kedua kalinya dan menunggu", s:4},{t:"Datang langsung dan berkoordinasi formal, membangun komunikasi yang baik, serta menawarkan bantuan timbal balik", s:5},{t:"Menunggu hingga mereka merespons", s:3},{t:"Melaporkan mereka ke pimpinan sebagai penghambat program", s:2},{t:"Memalsukan data agar program tetap berjalan", s:1}], ex:"Koordinasi lintas instansi membutuhkan pendekatan proaktif dan hubungan kerja yang saling menguntungkan."},
{id:"TKP-049", q:"Seorang CPNS baru di unit Anda kesulitan beradaptasi dengan sistem kerja. Sebagai senior, tindakan terbaik adalah ....", opts:[{t:"Membantunya hanya bila ia bertanya", s:4},{t:"Menjadi mentor: membimbing, memberi contoh, dan memantau perkembangannya", s:5},{t:"Membiarkannya belajar sendiri agar mandiri", s:3},{t:"Mengejeknya karena lambat beradaptasi", s:2},{t:"Melaporkan ke atasan bahwa ia tidak kompeten", s:1}], ex:"Membina junior adalah investasi tim; mentoring mempercepat kemandirian dan kekompakan."},
{id:"TKP-050", q:"Unit lain menolak berbagi informasi dengan alasan 'bukan urusanmu' (ego sektoral). Cara terbaik mengatasinya adalah ....", opts:[{t:"Bekerja tanpa data tersebut", s:3},{t:"Menjelaskan tujuan bersama program, mengajak dialog, dan melibatkan pimpinan bila perlu untuk membuka akses", s:5},{t:"Meminta atasan memfasilitasi koordinasi", s:4},{t:"Membalas dengan menutup akses informasi unit Anda", s:2},{t:"Menyebarkan bahwa unit tersebut tidak kooperatif", s:1}], ex:"Ego sektoral diatasi dengan menyamakan tujuan dan fasilitasi pimpinan, bukan dengan balasan."},
{id:"TKP-051", q:"Anda ditugaskan dalam tim gabungan penanggulangan bencana bersama dinas lain dan relawan. Sikap terbaik adalah ....", opts:[{t:"Menjalankan tugas sesuai perintah atasan langsung", s:4},{t:"Aktif berkoordinasi, memahami peran masing-masing pihak, dan menyesuaikan diri dengan komando lapangan", s:5},{t:"Bekerja sendiri sesuai kebiasaan dinas asal", s:3},{t:"Menunggu perintah tanpa inisiatif", s:2},{t:"Menolak bergabung karena bukan tugas pokok", s:1}], ex:"Kerja tim darurat menuntut adaptasi peran dan kepatuhan pada koordinasi bersama."},
{id:"TKP-052", q:"Seorang rekan senior sulit menerima ide baru yang Anda usulkan karena Anda lebih muda. Cara terbaik adalah ....", opts:[{t:"Menyampaikan ide melalui atasan", s:4},{t:"Menyampaikan ide dengan hormat, didukung data dan contoh keberhasilan, serta mengajak diskusi terbuka", s:5},{t:"Menyimpan ide untuk diri sendiri", s:3},{t:"Memaksakan ide karena merasa lebih paham perkembangan zaman", s:2},{t:"Meremehkan rekan senior di depan umum", s:1}], ex:"Ide baru diterima melalui komunikasi yang menghormati pengalaman senior dan berbasis bukti."},
{id:"TKP-053", q:"Pembagian tugas kelompok tidak adil dan Anda mendapat porsi terbanyak. Tindakan paling tepat adalah ....", opts:[{t:"Menerima sambil meminta bantuan rekan", s:4},{t:"Menyampaikan keberatan secara terbuka di forum tim dan mengusulkan pembagian ulang yang proporsional", s:5},{t:"Mengerjakan dengan menggerutu", s:3},{t:"Mengerjakan asal-asalan sebagai bentuk protes", s:2},{t:"Menolak mengerjakan sama sekali", s:1}], ex:"Ketidakadilan pembagian tugas diselesaikan melalui musyawarah tim, bukan protes pasif."},
{id:"TKP-054", q:"Unit Anda ingin membangun jejaring dengan komunitas dan LSM untuk program pemberdayaan. Langkah terbaik adalah ....", opts:[{t:"Mengundang mereka hanya saat ada acara", s:4},{t:"Memetakan komunitas yang relevan, menjalin komunikasi rutin, dan merancang kerja sama yang saling menguntungkan", s:5},{t:"Menunggu mereka datang menawarkan kerja sama", s:3},{t:"Menganggap LSM hanya mencari proyek", s:2},{t:"Menolak bekerja sama dengan pihak luar", s:1}], ex:"Jejaring dibangun proaktif melalui pemetaan dan komunikasi berkelanjutan, bukan insidental."},
{id:"TKP-055", q:"Anda menerima serah terima tugas dari pejabat yang mutasi. Yang paling tepat dilakukan adalah ....", opts:[{t:"Membaca dokumen serah terima", s:4},{t:"Mempelajari dokumen serah terima dengan cermat, berdiskusi dengan pendahulu, dan memastikan keberlanjutan program", s:5},{t:"Langsung bekerja dengan cara sendiri", s:3},{t:"Menyalahkan pendahulu bila ada masalah", s:2},{t:"Mengabaikan dokumen serah terima", s:1}], ex:"Keberlanjutan program dijaga melalui serah terima pengetahuan yang serius dan terdokumentasi."},
{id:"TKP-056", q:"Rapat koordinasi selalu molor karena peserta datang terlambat. Solusi terbaik yang dapat Anda usulkan adalah ....", opts:[{t:"Memulai rapat tepat waktu bagi yang sudah hadir", s:4},{t:"Mengusulkan dan menegakkan tata tertib rapat seperti tepat waktu dan agenda jelas yang disepakati bersama", s:5},{t:"Ikut datang terlambat agar tidak menunggu", s:3},{t:"Mengeluh tetapi tidak berbuat apa-apa", s:2},{t:"Tidak menghadiri rapat lagi", s:1}], ex:"Disiplin kolektif dibangun melalui aturan bersama yang ditegakkan secara konsisten."},
{id:"TKP-057", q:"Seorang rekan satu tim lambat menyelesaikan bagiannya sehingga menghambat pekerjaan Anda. Tindakan terbaik adalah ....", opts:[{t:"Mengingatkannya tentang tenggat waktu", s:4},{t:"Menawarkan bantuan dan mendiskusikan kendalanya untuk mencari solusi bersama", s:5},{t:"Mengerjakan bagiannya diam-diam", s:3},{t:"Melaporkannya ke atasan tanpa bicara terlebih dahulu", s:2},{t:"Membiarkannya gagal agar jera", s:1}], ex:"Hambatan rekan diatasi dengan empati dan bantuan, bukan dibiarkan atau langsung dilaporkan."},
{id:"TKP-058", q:"Terjadi perbedaan pandangan antara Anda dan atasan langsung soal prioritas pekerjaan. Sikap paling tepat adalah ....", opts:[{t:"Mengikuti perintah atasan meski berbeda pendapat", s:4},{t:"Menyampaikan pandangan dengan data dan alternatif solusi, lalu menjalankan keputusan akhir atasan dengan penuh tanggung jawab", s:5},{t:"Mengabaikan perintah dan mengerjakan versi sendiri", s:3},{t:"Mengadu ke pimpinan yang lebih tinggi", s:2},{t:"Menolak perintah secara terbuka", s:1}], ex:"Bawahan boleh menyampaikan masukan profesional, tetapi keputusan pimpinan yang sah wajib dijalankan."},
{id:"TKP-059", q:"Unit Anda diminta membantu unit lain yang kekurangan personel saat ada acara besar daerah. Sikap terbaik adalah ....", opts:[{t:"Membantu seadanya", s:4},{t:"Bersedia membantu dan berkoordinasi agar tugas pokok unit tetap berjalan", s:5},{t:"Menolak karena bukan tugas pokok unit", s:3},{t:"Membantu tetapi terus mengeluh", s:2},{t:"Berpura-pura sibuk agar tidak dilibatkan", s:1}], ex:"Semangat gotong royong antarunit diwujudkan dengan tetap menjaga tugas pokok masing-masing."},
{id:"TKP-060", q:"Seorang rekan yang bermasalah dengan Anda memuji Anda berlebihan di depan atasan untuk mencari muka. Respons paling tepat adalah ....", opts:[{t:"Mengucapkan terima kasih secukupnya", s:4},{t:"Menanggapi dengan profesional dan proporsional, tidak terbawa, serta tetap menjaga hubungan kerja yang baik", s:5},{t:"Menegurnya di depan atasan", s:3},{t:"Membalas dengan sindiran", s:2},{t:"Membongkar masalah dengannya di depan atasan", s:1}], ex:"Menjaga profesionalitas dan tidak terpancing emosi adalah respons terbaik dalam situasi tersebut."},{id:"TKP-061", q:"Seorang warga yang akan beribadah meminta pelayanannya dipercepat, padahal keyakinannya berbeda dengan Anda. Sikap terbaik adalah ....", opts:[{t:"Melayani seperti biasa dengan ramah tanpa perlakuan khusus", s:4},{t:"Menghormati kebutuhannya dan mengupayakan percepatan yang wajar sesuai urutan antrean", s:5},{t:"Menyuruhnya menunggu seperti warga lain tanpa empati", s:3},{t:"Mengabaikan alasannya", s:2},{t:"Mengejek keyakinannya", s:1}], ex:"Menghormati kebutuhan ibadah warga apa pun agamanya adalah wujud toleransi yang aktif."},
{id:"TKP-062", q:"Terjadi konflik antar kelompok warga yang berbeda suku mengenai pembagian bantuan sosial. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menjelaskan kriteria penerima secara resmi", s:4},{t:"Memfasilitasi dialog, menjelaskan kriteria penerima secara transparan, dan memastikan pembagian yang adil", s:5},{t:"Memihak kelompok yang lebih vokal agar cepat selesai", s:3},{t:"Menunda pembagian hingga konflik mereda sendiri", s:2},{t:"Membatalkan penyaluran bantuan", s:1}], ex:"Konflik horizontal diurai dengan transparansi kriteria dan fasilitasi dialog yang adil bagi semua pihak."},
{id:"TKP-063", q:"Seorang warga hanya fasih berbahasa daerah dan kesulitan memahami penjelasan Anda dalam bahasa Indonesia. Yang paling tepat adalah ....", opts:[{t:"Berbicara pelan dengan bahasa sederhana dibantu isyarat", s:4},{t:"Mencari penerjemah seperti rekan atau perangkat desa dan memastikan ia memahami hak dan kewajibannya", s:5},{t:"Memintanya kembali dengan membawa penerjemah", s:3},{t:"Melayani seadanya tanpa memastikan ia paham", s:2},{t:"Menolak melayani karena kendala bahasa", s:1}], ex:"Hak warga atas informasi harus dijamin dalam bahasa yang ia pahami."},
{id:"TKP-064", q:"Seorang rekan merayakan hari besar keagamaannya dan mengajak Anda mengikuti ritual ibadahnya. Sikap terbaik adalah ....", opts:[{t:"Mengucapkan selamat secukupnya", s:4},{t:"Mengucapkan selamat dengan tulus dan menghormatinya tanpa harus mengikuti ritual yang bukan keyakinan Anda", s:5},{t:"Mengabaikan ajakannya tanpa respons", s:3},{t:"Menolak dengan kasar", s:2},{t:"Mengejek perayaan keagamaannya", s:1}], ex:"Toleransi berarti menghormati perayaan orang lain tanpa mencampuradukkan keyakinan masing-masing."},
{id:"TKP-065", q:"Acara kantor bertepatan dengan masa puasa sebagian pegawai. Keputusan terbaik adalah ....", opts:[{t:"Tetap mengadakan tetapi memberi pilihan bagi yang berpuasa", s:4},{t:"Menyesuaikan jadwal dan menu acara agar semua pegawai dapat berpartisipasi dengan nyaman", s:5},{t:"Mengadakan seperti biasa tanpa penyesuaian", s:3},{t:"Membatalkan acara", s:2},{t:"Mengejek pegawai yang berpuasa", s:1}], ex:"Kegiatan bersama dirancang inklusif agar tidak mengecualikan siapa pun."},
{id:"TKP-066", q:"Seorang warga adat meminta surat keterangan dengan nama adat yang tidak lazim dalam sistem administrasi. Yang paling tepat adalah ....", opts:[{t:"Mencatat sesuai dokumen identitas resminya", s:4},{t:"Menghormati nama adatnya, mencatat sesuai dokumen resmi, dan membantu penyesuaian administrasi yang diperlukan", s:5},{t:"Memintanya memakai nama yang lebih umum", s:3},{t:"Menolak karena menyulitkan sistem", s:2},{t:"Mengejek namanya", s:1}], ex:"Identitas budaya warga adalah hak yang harus dihormati dalam pelayanan administrasi."},
{id:"TKP-067", q:"Stereotip negatif terhadap suku tertentu beredar di kalangan pegawai kantor Anda. Sikap Anda yang paling tepat adalah ....", opts:[{t:"Diam dan tidak ikut-ikutan", s:4},{t:"Tidak ikut menyebarkan, menegur dengan bijak, dan menilai orang berdasarkan perilaku individunya", s:5},{t:"Ikut tertawa agar diterima lingkungan", s:3},{t:"Ikut menyebarkan stereotip tersebut", s:2},{t:"Memprovokasi perlakuan diskriminatif", s:1}], ex:"ASN harus bebas dari prasangka kesukuan; setiap orang dinilai dari perilakunya, bukan stereotip kelompoknya."},
{id:"TKP-068", q:"Kelompok warga minoritas agama kesulitan mendapatkan izin pendirian tempat ibadah. Sebagai petugas perizinan, Anda harus ....", opts:[{t:"Memproses seperti pemohon lainnya", s:4},{t:"Memproses sesuai aturan yang berlaku secara adil tanpa diskriminasi", s:5},{t:"Memperlambat dengan alasan kelengkapan prosedur", s:3},{t:"Menolak dengan alasan keresahan warga sekitar", s:2},{t:"Memprovokasi warga menolak pendirian tersebut", s:1}], ex:"Kebebasan beribadah dijamin konstitusi; pelayanan perizinan harus netral dan adil bagi semua."},
{id:"TKP-069", q:"Kegiatan gotong royong membersihkan lingkungan kantor sepi peminat karena sebagian pegawai enggan ikut. Sikap Anda adalah ....", opts:[{t:"Ikut serta dalam kegiatan", s:4},{t:"Ikut aktif dan mengajak dengan keteladanan tanpa memaksa", s:5},{t:"Ikut tetapi bersikap pasif", s:3},{t:"Tidak ikut dengan alasan sibuk", s:2},{t:"Mengejek kegiatan tersebut", s:1}], ex:"Keteladanan dalam gotong royong lebih efektif menggerakkan orang daripada paksaan."},
{id:"TKP-070", q:"Musyawarah warga mengalami kebuntuan antara dua kubu mengenai lokasi posyandu. Peran Anda sebagai fasilitator adalah ....", opts:[{t:"Memutuskan berdasarkan suara terbanyak", s:4},{t:"Memfasilitasi musyawarah lanjutan dengan data objektif dan mencari solusi yang menguntungkan semua pihak", s:5},{t:"Memihak kubu yang dekat dengan Anda", s:3},{t:"Menunda tanpa batas waktu yang jelas", s:2},{t:"Membubarkan musyawarah", s:1}], ex:"Fasilitasi yang netral dan berbasis data membantu para pihak mencapai mufakat."},
{id:"TKP-071", q:"Seorang rekan yang berbeda keyakinan berdoa dengan caranya sebelum rapat dimulai. Sikap Anda yang paling tepat adalah ....", opts:[{t:"Menunggu dengan sabar", s:4},{t:"Menghormatinya dengan diam dan memberinya ruang", s:5},{t:"Memintanya berdoa nanti saja agar rapat cepat mulai", s:3},{t:"Mengajak peserta lain mengobrol agar ia terganggu", s:2},{t:"Mengejek ritual doanya", s:1}], ex:"Menghormati ibadah orang lain adalah bentuk toleransi yang paling dasar."},
{id:"TKP-072", q:"Hidangan dalam rapat mengandung bahan yang tidak dapat dikonsumsi sebagian peserta karena alasan agama atau kesehatan. Yang paling tepat adalah ....", opts:[{t:"Menanyakan kebutuhan khusus sebelum memesan hidangan", s:4},{t:"Memastikan selalu tersedia pilihan menu yang dapat dinikmati semua peserta", s:5},{t:"Membiarkan mereka tidak makan", s:3},{t:"Menyuruh mereka membawa bekal sendiri", s:2},{t:"Mengejek pantangan mereka", s:1}], ex:"Perhatian pada kebutuhan konsumsi semua peserta menunjukkan penghargaan terhadap keberagaman."},
{id:"TKP-073", q:"Warga pendatang diperlakukan berbeda oleh warga lokal dalam pembagian bantuan. Sebagai petugas, Anda harus ....", opts:[{t:"Menjelaskan kriteria resmi kepada semua pihak", s:4},{t:"Memastikan kriteria bantuan diterapkan setara tanpa membedakan asal-usul penerima", s:5},{t:"Mengikuti kebiasaan warga lokal", s:3},{t:"Memprioritaskan warga lokal", s:2},{t:"Mengeluarkan pendatang dari daftar penerima", s:1}], ex:"Keadilan distributif tidak mengenal dikotomi pendatang versus warga lokal."},
{id:"TKP-074", q:"Kearifan lokal masyarakat bertentangan dengan program yang akan dijalankan pemerintah. Pendekatan terbaik adalah ....", opts:[{t:"Menjelaskan tujuan program dengan hormat kepada tokoh masyarakat", s:4},{t:"Berdialog dengan tokoh adat untuk mencari titik temu agar program berjalan selaras dengan adat setempat", s:5},{t:"Memaksakan program karena aturan dari pusat", s:3},{t:"Membatalkan program secara sepihak", s:2},{t:"Merendahkan adat setempat", s:1}], ex:"Program menjadi efektif bila diselaraskan dengan kearifan lokal melalui dialog yang menghormati."},
{id:"TKP-075", q:"Anak buah Anda didiskriminasi rekan kerja karena logat daerahnya. Sebagai pimpinan, tindakan Anda adalah ....", opts:[{t:"Menasihati pelaku secara pribadi", s:4},{t:"Menegur pelaku, membela korban, dan menegaskan bahwa keberagaman adalah kekuatan tim", s:5},{t:"Membiarkan karena dianggap candaan biasa", s:3},{t:"Ikut menertawakan", s:2},{t:"Memindahkan korban agar tidak mengganggu", s:1}], ex:"Diskriminasi dalam bentuk apa pun harus ditindak tegas oleh pimpinan."},
{id:"TKP-076", q:"Anda menerima surel yang mengatasnamakan pimpinan dan meminta Anda mengklik tautan untuk verifikasi data. Tindakan paling aman adalah ....", opts:[{t:"Mengabaikan surel tersebut", s:4},{t:"Tidak mengklik atau merespons, memverifikasi langsung ke pimpinan, dan melaporkannya ke tim keamanan siber", s:5},{t:"Membalas surel untuk menanyakan kebenarannya", s:3},{t:"Mengklik tautannya untuk memastikan", s:2},{t:"Mengikuti instruksi dalam surel", s:1}], ex:"Verifikasi melalui jalur resmi dan pelaporan adalah respons standar terhadap dugaan phishing."},
{id:"TKP-077", q:"Laptop dinas berisi data warga hilang. Langkah pertama yang paling tepat adalah ....", opts:[{t:"Melapor ke atasan", s:4},{t:"Segera melapor ke atasan dan tim TI, mengunci akses dari jarak jauh bila memungkinkan, serta mendokumentasikan kronologi", s:5},{t:"Mencari sendiri diam-diam", s:3},{t:"Berharap data tidak disalahgunakan", s:2},{t:"Menyembunyikan kejadian tersebut", s:1}], ex:"Insiden keamanan data wajib dilaporkan segera agar langkah mitigasi dapat dilakukan."},
{id:"TKP-078", q:"Hoaks tentang kebijakan dinas Anda viral di grup WhatsApp warga. Respons terbaik adalah ....", opts:[{t:"Menyampaikan klarifikasi singkat", s:4},{t:"Membuat klarifikasi resmi yang mudah dipahami dan menyebarkannya melalui kanal resmi serta grup warga", s:5},{t:"Mengabaikan karena nanti juga reda sendiri", s:3},{t:"Membalas dengan emosi di grup", s:2},{t:"Menyebarkan informasi tandingan yang belum terverifikasi", s:1}], ex:"Hoaks dilawan dengan klarifikasi resmi yang cepat dan mudah dipahami masyarakat."},
{id:"TKP-079", q:"Aplikasi pelayanan error pada jam sibuk dan antrean warga mengular. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Melapor ke tim TI dan menunggu perbaikan", s:4},{t:"Segera melapor ke tim TI, menginformasikan kondisi kepada warga dengan jujur, dan menyiapkan layanan manual sementara", s:5},{t:"Menyuruh warga pulang dan kembali lain waktu", s:3},{t:"Menyalahkan vendor di depan warga", s:2},{t:"Membiarkan warga menunggu tanpa informasi", s:1}], ex:"Gangguan sistem diatasi dengan pelaporan cepat, komunikasi jujur, dan solusi sementara."},
{id:"TKP-080", q:"Seorang warga lanjut usia kesulitan menggunakan aplikasi layanan daring. Bantuan terbaik adalah ....", opts:[{t:"Memberikan panduan tertulis bergambar", s:4},{t:"Membimbing dengan sabar langkah demi langkah atau menawarkan bantuan pengisian langsung", s:5},{t:"Menyuruh anaknya yang menguruskan", s:3},{t:"Menyuruhnya datang langsung ke kantor saja", s:2},{t:"Menolak membantu karena sudah ada aplikasi", s:1}], ex:"Literasi digital warga adalah bagian dari pelayanan; bimbingan yang sabar menjembatani kesenjangan digital."},
{id:"TKP-081", q:"Seorang rekan membagikan kata sandi akun sistemnya kepada orang luar dengan alasan kepraktisan. Sikap Anda adalah ....", opts:[{t:"Menegur rekan tersebut", s:4},{t:"Menegur, memintanya segera mengganti kata sandi, dan melaporkan bila berisiko pada keamanan data", s:5},{t:"Membiarkan karena bukan urusan Anda", s:3},{t:"Ikut memakai akunnya", s:2},{t:"Meminta kata sandinya untuk dipakai bersama", s:1}], ex:"Kredensial adalah tanggung jawab pribadi; pembagian akun melanggar keamanan sistem informasi."},
{id:"TKP-082", q:"Anda diminta mengunggah konten ke media sosial resmi dinas. Yang paling tepat dilakukan adalah ....", opts:[{t:"Mengunggah setelah memeriksa isinya", s:4},{t:"Memastikan konten akurat, sesuai pedoman komunikasi publik, dan mendapat persetujuan pejabat berwenang sebelum diunggah", s:5},{t:"Mengunggah apa adanya sesuai perintah", s:3},{t:"Mengunggah tanpa izin terlebih dahulu", s:2},{t:"Mengunggah konten pribadi melalui akun dinas", s:1}], ex:"Akun resmi mewakili institusi; setiap konten harus akurat dan terotorisasi."},
{id:"TKP-083", q:"Pimpinan meminta digitalisasi arsip fisik yang menumpuk. Pendekatan kerja terbaik adalah ....", opts:[{t:"Memindai dokumen satu per satu", s:4},{t:"Menyusun rencana kerja meliputi prioritas, klasifikasi, dan pencadangan, lalu mengerjakannya sistematis dengan menjaga kerahasiaan dokumen", s:5},{t:"Menunda karena pekerjaan merepotkan", s:3},{t:"Membuang arsip lama tanpa pendataan", s:2},{t:"Menolak dengan alasan bukan tugas Anda", s:1}], ex:"Digitalisasi dikerjakan terencana dengan memperhatikan klasifikasi dan keamanan dokumen."},
{id:"TKP-084", q:"Anda menemukan rekan menginstal aplikasi bajakan di komputer dinas. Tindakan paling tepat adalah ....", opts:[{t:"Mengingatkan rekan tersebut", s:4},{t:"Mengingatkan tentang risikonya seperti malware dan pelanggaran hukum, serta melaporkan ke tim TI bila tidak diindahkan", s:5},{t:"Membiarkannya", s:3},{t:"Ikut meminta file installernya", s:2},{t:"Ikut menginstal di komputer Anda", s:1}], ex:"Perangkat lunak ilegal membahayakan keamanan sistem dan melanggar hukum; wajib dicegah."},
{id:"TKP-085", q:"Seorang rekan meminta 'meminjam' tanda tangan elektronik Anda untuk dokumen yang mendesak. Respons terbaik adalah ....", opts:[{t:"Menolak dengan halus", s:4},{t:"Menolak karena tanda tangan elektronik bersifat personal dan memiliki kekuatan hukum", s:5},{t:"Meminjamkan sekali saja", s:3},{t:"Meminjamkan dengan imbalan", s:2},{t:"Memberikan PIN-nya sekalian", s:1}], ex:"Tanda tangan elektronik setara tanda tangan basah; meminjamkannya berarti menyerahkan tanggung jawab hukum."},
{id:"TKP-086", q:"Seorang rekan menyebarkan paham yang mempertentangkan Pancasila di grup WhatsApp kantor. Sikap Anda yang paling tepat adalah ....", opts:[{t:"Menegur rekan tersebut", s:4},{t:"Tidak ikut menyebarkan, menegur dengan bijak, dan melaporkan ke atasan atau bidang terkait bila berlanjut", s:5},{t:"Keluar dari grup tanpa berbuat apa-apa", s:3},{t:"Ikut menyimak dan menyebarkannya", s:2},{t:"Ikut menyebarkan dan mengajak rekan lain", s:1}], ex:"ASN wajib setia pada Pancasila; penyebaran paham anti-Pancasila harus dicegah dan dilaporkan."},
{id:"TKP-087", q:"Anda mendapat ajakan mengikuti aksi yang berpotensi anarkis dengan mengatasnamakan agama. Tindakan terbaik adalah ....", opts:[{t:"Menolak ajakan tersebut", s:4},{t:"Menolak dengan tegas dan mengingatkan pengajak tentang aturan serta netralitas ASN", s:5},{t:"Ikut sebagai penonton saja", s:3},{t:"Ikut serta dalam aksi", s:2},{t:"Menjadi koordinator aksi", s:1}], ex:"ASN dilarang terlibat aksi anarkis; penolakan tegas menjaga netralitas aparatur."},
{id:"TKP-088", q:"Konten intoleran terhadap kelompok agama lain beredar di media sosial dan dibagikan oleh rekan Anda. Sikap terbaik adalah ....", opts:[{t:"Tidak ikut membagikan konten tersebut", s:4},{t:"Tidak ikut membagikan, memberikan pemahaman tentang toleransi, dan melaporkan konten bila mengandung ujaran kebencian", s:5},{t:"Membiarkannya", s:3},{t:"Ikut membagikan", s:2},{t:"Menambahkan komentar provokatif", s:1}], ex:"Ujaran kebencian dilawan dengan tidak menyebarkan serta edukasi tentang toleransi."},
{id:"TKP-089", q:"Seseorang menawarkan 'kajian' tertutup yang mengajarkan penolakan terhadap pemerintah yang sah. Respons Anda adalah ....", opts:[{t:"Menolak tawaran tersebut", s:4},{t:"Menolak dan melaporkan ke pihak berwenang karena berpotensi menyebarkan paham radikal", s:5},{t:"Ikut sekali untuk mengetahui isinya", s:3},{t:"Ikut secara rutin", s:2},{t:"Mengajak rekan lain untuk ikut", s:1}], ex:"Paham yang menolak pemerintahan yang sah bertentangan dengan sumpah ASN; wajib ditolak dan dilaporkan."},
{id:"TKP-090", q:"Seorang rekan menyatakan tidak mau dipimpin atasan yang berbeda suku dan agama dengannya. Tindakan Anda yang paling tepat adalah ....", opts:[{t:"Menasihati rekan tersebut", s:4},{t:"Menasihati bahwa kepemimpinan dinilai dari kompetensi, serta mengingatkan tentang nilai persatuan dan netralitas ASN", s:5},{t:"Membiarkan karena itu hak pribadinya", s:3},{t:"Setuju dengan pendapatnya", s:2},{t:"Ikut menggalang penolakan terhadap atasan", s:1}], ex:"Penolakan berbasis SARA bertentangan dengan Bhinneka Tunggal Ika dan prinsip meritokrasi ASN."},
];